//! haulmer-connect core: maps the person's selection to a `gws` login, reports status,
//! revokes access and installs agent skills.
//!
//! The whole behaviour sits behind [`Core`], built from injected [`Paths`] and two ports,
//! [`ProcessRunner`] and [`HttpClient`]. Each ticket owns one module and adds its
//! `impl Core { ... }` block there, so tickets do not edit this file.
//!
//! | Module | Ticket | Provides |
//! |---|---|---|
//! | [`scopes`] | T02 | selection <-> scopes, defaults, UI catalogue |
//! | [`gws_binary`] | T03 | `Core::find_gws`, `Core::ensure_gws` |
//! | [`system_http`] | T03 | real [`HttpClient`] |
//! | [`settings`] | T04 | `Core::settings`, `set_config_dir`, `set_key_storage` |
//! | [`gws_env`] | T04 | `Core::gws_command`, credential and marker helpers |
//! | [`status`] | T05 | `Core::status` |
//! | [`revoke`] | T06 | `Core::revoke_all` |
//! | [`save`] | T07 | `Core::save`, `Core::cancel_login` |
//! | [`skills`] | T08 | `Core::install_skills` |
//!
//! # Example
//!
//! ```no_run
//! use haulmer_connect_core::{Core, Paths};
//! let core = Core::system(Paths { home: "/home/ana".into(), app_data: "/home/ana/.haulmer".into() });
//! let status = core.status();
//! ```

use std::sync::{Arc, Mutex};

pub mod gws_binary;
pub mod gws_env;
pub mod oauth_client;
mod ports;
pub mod revoke;
pub mod save;
pub mod scopes;
pub mod settings;
pub mod skills;
pub mod status;
pub mod system_http;
mod system_runner;
#[cfg(any(test, feature = "testing"))]
pub mod testing;
mod types;

pub use ports::{
    CommandSpec, HttpClient, HttpResponse, KILLED_EXIT_CODE, OutputLine, ProcessKiller,
    ProcessOutput, ProcessRunner, RunningProcess,
};
pub use system_http::SystemHttp;
pub use system_runner::SystemRunner;
pub use types::{
    CoreError, InstalledSkills, KeyStorage, Level, Paths, SaveOutcome, Selection, Service,
    ServiceInfo, ServiceLevel, Settings, Status,
};

/// The core. Thread-safe: the Tauri layer shares one instance across commands, so
/// `cancel_login` can run while `save` blocks on the login.
///
/// Module code reads the fields directly (they are visible to every module of this crate).
///
/// # Example
///
/// ```
/// use std::sync::Arc;
/// use haulmer_connect_core::{Core, Paths, SystemHttp, SystemRunner};
/// let paths = Paths { home: "/home/ana".into(), app_data: "/tmp/haulmer".into() };
/// let core = Core::new(paths, Arc::new(SystemRunner), Arc::new(SystemHttp::new()));
/// assert_eq!(core.paths().home, std::path::PathBuf::from("/home/ana"));
/// ```
pub struct Core {
    /// Injected folders.
    paths: Paths,
    /// Runs gws.
    #[allow(dead_code)] // used from T03 on
    runner: Arc<dyn ProcessRunner>,
    /// Downloads and the revoke call.
    #[allow(dead_code)] // used from T03 on
    http: Arc<dyn HttpClient>,
    /// Killer of the login `save` is waiting on. `cancel_login` takes it and kills;
    /// `save` takes it after the process ends: finding it gone means the login was cancelled.
    #[allow(dead_code)] // used by T07
    active_login: Mutex<Option<Arc<dyn ProcessKiller>>>,
}

impl Core {
    /// Builds the core from injected folders and ports (tests pass temp dirs and fakes).
    ///
    /// # Example
    ///
    /// ```
    /// use std::sync::Arc;
    /// use haulmer_connect_core::{Core, Paths, SystemHttp, SystemRunner};
    /// let paths = Paths { home: "/home/ana".into(), app_data: "/tmp/haulmer".into() };
    /// let core = Core::new(paths, Arc::new(SystemRunner), Arc::new(SystemHttp::new()));
    /// ```
    pub fn new(paths: Paths, runner: Arc<dyn ProcessRunner>, http: Arc<dyn HttpClient>) -> Self {
        Self {
            paths,
            runner,
            http,
            active_login: Mutex::new(None),
        }
    }

    /// Builds the core with the real adapters ([`SystemRunner`], [`SystemHttp`]); used by the app.
    ///
    /// # Example
    ///
    /// ```
    /// use haulmer_connect_core::{Core, Paths};
    /// let core = Core::system(Paths { home: "/home/ana".into(), app_data: "/tmp/haulmer".into() });
    /// ```
    pub fn system(paths: Paths) -> Self {
        Self::new(paths, Arc::new(SystemRunner), Arc::new(SystemHttp::new()))
    }

    /// The injected folders.
    ///
    /// # Example
    ///
    /// ```
    /// use haulmer_connect_core::{Core, Paths};
    /// let paths = Paths { home: "/home/ana".into(), app_data: "/tmp/haulmer".into() };
    /// assert_eq!(Core::system(paths.clone()).paths(), &paths);
    /// ```
    pub fn paths(&self) -> &Paths {
        &self.paths
    }
}
